FROM webhooks_dispatches
	JOIN webhooks_deliveries ON webhooks_dispatches.delivery_id=webhooks_deliveries.id
	JOIN webhooks_endpoints ON webhooks_dispatches.endpoint_id=webhooks_endpoints.id
WHERE webhooks_endpoints.disabled = FALSE
	AND webhooks_endpoints.archived_at IS NULL
	AND webhooks_dispatches.id IN (sqlc.slice(ids))
ORDER BY webhooks_dispatches.created_at, webhooks_dispatches.id;

