	LIMIT COALESCE(sqlc.narg(result_limit), 50)
);

-- name: ReapDeliveries :execrows
DELETE FROM webhooks_deliveries
WHERE webhooks_deliveries.id IN (
	SELECT webhooks_deliveries.id
	FROM webhooks_deliveries
	WHERE NOT EXISTS (
		SELECT 1
		FROM webhooks_dispatches
		WHERE webhooks_dispatches.delivery_id = webhooks_deliveries.id
	)
	LIMIT COALESCE(sqlc.narg(result_limit), 50)
);

-- name: InsertAttempt :exec
INSERT INTO webhooks_attempts (
	id,
	delivery_id,
	endpoint_id,
	attempt_count,
	status_code,
	error,
	duration_ms,
	created_at
) VALUES (
	sqlc.arg(id),
	sqlc.arg(delivery_id),
	sqlc.arg(endpoint_id),
	sqlc.arg(attempt_count),
	sqlc.arg(status_code),
	sqlc.narg(error),
	sqlc.arg(duration_ms),
	sqlc.arg(created_at)
);

-- name: ListAttempts :many
SELECT
	webhooks_attempts.id,
	webhooks_attempts.delivery_id,
	webhooks_attempts.endpoint_id,
	webhooks_attempts.attempt_count,
	webhooks_attempts.status_code,
	webhooks_attempts.error,
	webhooks_attempts.duration_ms,
	webhooks_attempts.created_at,
	webhooks_attempts.last_updated_at,
	webhooks_attempts.archived_at,
	(
		SELECT COUNT(webhooks_attempts.id)
		FROM webhooks_attempts
		JOIN webhooks_deliveries ON webhooks_attempts.delivery_id=webhooks_deliveries.id
		WHERE webhooks_attempts.created_at > COALESCE(sqlc.narg(created_after), (SELECT datetime(CURRENT_TIMESTAMP, '-999 years')))
			AND webhooks_attempts.created_at < COALESCE(sqlc.narg(created_before), (SELECT datetime(CURRENT_TIMESTAMP, '+999 years')))
			AND (
				webhooks_attempts.last_updated_at IS NULL
				OR webhooks_attempts.last_updated_at > COALESCE(sqlc.narg(updated_after), (SELECT datetime(CURRENT_TIMESTAMP, '-999 years')))
			)
			AND (
				webhooks_attempts.last_updated_at IS NULL
				OR webhooks_attempts.last_updated_at < COALESCE(sqlc.narg(updated_before), (SELECT datetime(CURRENT_TIMESTAMP, '+999 years')))
			)
			AND (COALESCE(sqlc.narg(include_archived), false) = true OR webhooks_attempts.archived_at IS NULL)
			AND webhooks_attempts.delivery_id = sqlc.arg(delivery_id)
			AND webhooks_deliveries.scope = sqlc.arg(scope)
	) AS filtered_count,
	(
		SELECT COUNT(webhooks_attempts.id)
		FROM webhooks_attempts
		JOIN webhooks_deliveries ON webhooks_attempts.delivery_id=webhooks_deliveries.id
		WHERE (COALESCE(sqlc.narg(include_archived), false) = true OR webhooks_attempts.archived_at IS NULL)
			AND webhooks_attempts.delivery_id = sqlc.arg(delivery_id)
			AND webhooks_deliveries.scope = sqlc.arg(scope)
	) AS total_count
FROM webhooks_attempts
JOIN webhooks_deliveries ON webhooks_attempts.delivery_id=webhooks_deliveries.id
WHERE webhooks_attempts.created_at > COALESCE(sqlc.narg(created_after), (SELECT datetime(CURRENT_TIMESTAMP, '-999 years')))
	AND webhooks_attempts.created_at < COALESCE(sqlc.narg(created_before), (SELECT datetime(CURRENT_TIMESTAMP, '+999 years')))
	AND (
		webhooks_attempts.last_updated_at IS NULL
		OR webhooks_attempts.last_updated_at > COALESCE(sqlc.narg(updated_after), (SELECT datetime(CURRENT_TIMESTAMP, '-999 years')))
	)
	AND (
		webhooks_attempts.last_updated_at IS NULL
		OR webhooks_attempts.last_updated_at < COALESCE(sqlc.narg(updated_before), (SELECT datetime(CURRENT_TIMESTAMP, '+999 years')))
	)
	AND (COALESCE(sqlc.narg(include_archived), false) = true OR webhooks_attempts.archived_at IS NULL)
	AND webhooks_attempts.delivery_id = sqlc.arg(delivery_id)
	AND webhooks_deliveries.scope = sqlc.arg(scope)
	AND webhooks_attempts.id > COALESCE(sqlc.narg(page_cursor), '')
ORDER BY webhooks_attempts.id ASC
LIMIT COALESCE(sqlc.narg(result_limit), 50);

